INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CI001', 'HDSAT-RW-M19-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A placebo ( pluh-SEE-boh) is a medicine or treatment intended to appear genuine to its recipient, but which has no pharmaceutical effect. Common placebos include inert tablets (like sugar pills), inert injections (like saline), sham surgery, and other procedures. Placebos are used in randomized clinical trials to test the efficacy of medical treatments. In a placebo-controlled trial, any change in the control group is known as the placebo response, and the difference between this and the result of no treatment is the placebo effect. Placebos in clinical trials should ideally be indistinguishable from so-called verum treatments under investigation, except for the latter''s particular hypothesized medicinal effect. This is to shield test participants (with their consent) from knowing who is getting the placebo and who is getting the treatment under test, as patients'' and clinicians'' expectations of efficacy can influence results. The idea of a "placebo effect" was discussed in 18th century psychology, but became more prominent in the 20th century. Modern studies find that placebos can affect some outcomes such as pain and nausea, but otherwise do not generally have important clinical effects. Improvements that patients experience after being treated with a placebo can also be due to unrelated factors, such as regression to the mean (a statistical effect where an unusually high or low measurement is likely to be followed by a less extreme one).', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Placebos are inert treatments used to test real ones, and although they can affect some symptoms, improvement may have other causes."}, {"id": "B", "text": "Placebos are used in trials only when no real treatment exists."}, {"id": "C", "text": "Placebo effects have been shown to cure most medical conditions."}, {"id": "D", "text": "Placebos are active medicines that produce effects similar to the treatments under study."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Placebo", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Placebo', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CI001', 'A', ARRAY['A']::TEXT[], 'The passage defines placebos and their role in trials, explains blinding, and cautions that improvements after placebo may reflect limited effects or unrelated factors such as regression to the mean.', '{"D": "The text says placebos have no pharmaceutical effect.", "C": "The text says placebos can affect some outcomes such as pain and nausea but otherwise do not generally have important clinical effects.", "B": "The text says placebos are used in randomized clinical trials to test the efficacy of medical treatments."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-INF001', 'HDSAT-RW-M19-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'A placebo ( pluh-SEE-boh) is a medicine or treatment intended to appear genuine to its recipient, but which has no pharmaceutical effect. Common placebos include inert tablets (like sugar pills), inert injections (like saline), sham surgery, and other procedures. Placebos are used in randomized clinical trials to test the efficacy of medical treatments. In a placebo-controlled trial, any change in the control group is known as the placebo response, and the difference between this and the result of no treatment is the placebo effect. Placebos in clinical trials should ideally be indistinguishable from so-called verum treatments under investigation, except for the latter''s particular hypothesized medicinal effect. This is to shield test participants (with their consent) from knowing who is getting the placebo and who is getting the treatment under test, as patients'' and clinicians'' expectations of efficacy can influence results. The idea of a "placebo effect" was discussed in 18th century psychology, but became more prominent in the 20th century. Modern studies find that placebos can affect some outcomes such as pain and nausea, but otherwise do not generally have important clinical effects. Improvements that patients experience after being treated with a placebo can also be due to unrelated factors, such as regression to the mean (a statistical effect where an unusually high or low measurement is likely to be followed by a less extreme one).
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-INF001', 'C', ARRAY['C']::TEXT[], 'Regression to the mean is a statistical effect in which an extreme measurement is followed by a less extreme one, so improvement need not be caused by the placebo.', '{"A": "The text says placebos have no pharmaceutical effect and no active ingredient.", "D": "In a placebo-controlled trial, the placebo group does not receive the treatment under study.", "B": "The text says placebos generally lack important clinical effects beyond outcomes such as pain and nausea."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-TS001', 'HDSAT-RW-M19-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A placebo ( pluh-SEE-boh) is a medicine or treatment intended to appear genuine to its recipient, but which has no pharmaceutical effect. Common placebos include inert tablets (like sugar pills), inert injections (like saline), sham surgery, and other procedures. Placebos are used in randomized clinical trials to test the efficacy of medical treatments. In a placebo-controlled trial, any change in the control group is known as the placebo response, and the difference between this and the result of no treatment is the placebo effect. Placebos in clinical trials should ideally be indistinguishable from so-called verum treatments under investigation, except for the latter''s particular hypothesized medicinal effect. This is to shield test participants (with their consent) from knowing who is getting the placebo and who is getting the treatment under test, as patients'' and clinicians'' expectations of efficacy can influence results. The idea of a "placebo effect" was discussed in 18th century psychology, but became more prominent in the 20th century. Modern studies find that placebos can affect some outcomes such as pain and nausea, but otherwise do not generally have important clinical effects. Improvements that patients experience after being treated with a placebo can also be due to unrelated factors, such as regression to the mean (a statistical effect where an unusually high or low measurement is likely to be followed by a less extreme one).', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It traces the history of placebo research from the 18th century to modern studies."}, {"id": "B", "text": "It argues that placebo-controlled trials should be abandoned."}, {"id": "C", "text": "It compares placebo effects with the effects of surgery."}, {"id": "D", "text": "It defines placebos and their role in trials, explains why trials are blinded, and qualifies the placebo effect."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Placebo", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Placebo', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-TS001', 'D', ARRAY['D']::TEXT[], 'The text builds from definition and use, to blinding and expectations, to the limited scope of placebo effects and alternative explanations.', '{"A": "The text mentions 18th-century psychology in one sentence but does not trace a history.", "B": "The text describes placebo-controlled trials as the setting for testing treatments, not as a practice to abandon.", "C": "Surgery appears only in the list of placebo forms, such as sham surgery."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CE001', 'HDSAT-RW-M19-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A placebo ( pluh-SEE-boh) is a medicine or treatment intended to appear genuine to its recipient, but which has no pharmaceutical effect. Common placebos include inert tablets (like sugar pills), inert injections (like saline), sham surgery, and other procedures. Placebos are used in randomized clinical trials to test the efficacy of medical treatments. In a placebo-controlled trial, any change in the control group is known as the placebo response, and the difference between this and the result of no treatment is the placebo effect. Placebos in clinical trials should ideally be indistinguishable from so-called verum treatments under investigation, except for the latter''s particular hypothesized medicinal effect. This is to shield test participants (with their consent) from knowing who is getting the placebo and who is getting the treatment under test, as patients'' and clinicians'' expectations of efficacy can influence results. The idea of a "placebo effect" was discussed in 18th century psychology, but became more prominent in the 20th century. Modern studies find that placebos can affect some outcomes such as pain and nausea, but otherwise do not generally have important clinical effects. Improvements that patients experience after being treated with a placebo can also be due to unrelated factors, such as regression to the mean (a statistical effect where an unusually high or low measurement is likely to be followed by a less extreme one).', 'Which quotation from the text most directly supports the claim that placebo effects are limited to particular outcomes?', '[{"id": "A", "text": "The idea of a \"placebo effect\" was discussed in 18th century psychology, but became more prominent in the 20th century."}, {"id": "B", "text": "Modern studies find that placebos can affect some outcomes such as pain and nausea, but otherwise do not generally have important clinical effects."}, {"id": "C", "text": "Common placebos include inert tablets (like sugar pills), inert injections (like saline), sham surgery, and other procedures."}, {"id": "D", "text": "Placebos are used in randomized clinical trials to test the efficacy of medical treatments."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Placebo", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Placebo', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CE001', 'B', ARRAY['B']::TEXT[], 'The correct quotation names the specific outcomes placebos can affect and denies broad clinical effects.', '{"C": "This sentence lists examples of placebos.", "D": "This sentence describes how placebos are used in trials.", "A": "This sentence gives the history of the concept."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CI002', 'HDSAT-RW-M19-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'In bilingual education, students are taught in two (or more) languages. It is distinct from learning a second language as a subject because both languages are used for instruction in different content areas like math, science, and history. The time spent in each language depends on the model. For example, some models focus on providing education in both languages throughout a student''s entire education while others gradually transition to education in only one language. The ultimate goal of bilingual education is fluency and literacy in both languages through a variety of strategies such as translanguaging and recasting. Research on bilingual education has increased since 2008 with translanguaging and culturally responsive pedagogies. New educational models focus on inclusivity for hard of hearing or deaf students with the integration of sign language bilingual education. == Bilingual education program models == There are different ways to categorize bilingual education models, one of the most common being distinguishing their end goal. === Maintenance bilingual education === In a maintenance bilingual education program, the goal is for students to continue to learn about and in both languages for the majority of their education. Students in a maintenance bilingual education program should graduate being able to have a discussion about any content area in either language.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Bilingual education is designed only for students who already speak both languages."}, {"id": "B", "text": "Bilingual education uses two languages to teach content, differs from language study, and varies in how long each language is used."}, {"id": "C", "text": "All bilingual education programs transition to one language after the first year."}, {"id": "D", "text": "Bilingual education teaches a second language only as a separate subject."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Bilingual education", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Bilingual_education', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CI002', 'B', ARRAY['B']::TEXT[], 'The passage defines bilingual education by its use of two languages for instruction, notes that time in each language varies by model, and describes the goal of fluency and literacy in both.', '{"D": "The text says bilingual education is distinct from learning a second language as a subject.", "C": "The text says some models provide education in both languages throughout a student''s entire education.", "A": "The text describes models for students generally, including sign language bilingual education for deaf and hard of hearing students."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-INF002', 'HDSAT-RW-M19-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In bilingual education, students are taught in two (or more) languages. It is distinct from learning a second language as a subject because both languages are used for instruction in different content areas like math, science, and history. The time spent in each language depends on the model. For example, some models focus on providing education in both languages throughout a student''s entire education while others gradually transition to education in only one language. The ultimate goal of bilingual education is fluency and literacy in both languages through a variety of strategies such as translanguaging and recasting. Research on bilingual education has increased since 2008 with translanguaging and culturally responsive pedagogies. New educational models focus on inclusivity for hard of hearing or deaf students with the integration of sign language bilingual education. == Bilingual education program models == There are different ways to categorize bilingual education models, one of the most common being distinguishing their end goal. === Maintenance bilingual education === In a maintenance bilingual education program, the goal is for students to continue to learn about and in both languages for the majority of their education. Students in a maintenance bilingual education program should graduate being able to have a discussion about any content area in either language.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-INF002', 'B', ARRAY['B']::TEXT[], 'The passage states the maintenance model''s outcome directly: graduates should be able to discuss any content area in either language.', '{"D": "The text says students in a maintenance program should graduate able to discuss any content area in either language.", "A": "The program is designed for continued learning in both languages, not limited conversational use of one.", "C": "The text describes graduation outcomes, not professional certification."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-TS002', 'HDSAT-RW-M19-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'In bilingual education, students are taught in two (or more) languages. It is distinct from learning a second language as a subject because both languages are used for instruction in different content areas like math, science, and history. The time spent in each language depends on the model. For example, some models focus on providing education in both languages throughout a student''s entire education while others gradually transition to education in only one language. The ultimate goal of bilingual education is fluency and literacy in both languages through a variety of strategies such as translanguaging and recasting. Research on bilingual education has increased since 2008 with translanguaging and culturally responsive pedagogies. New educational models focus on inclusivity for hard of hearing or deaf students with the integration of sign language bilingual education. == Bilingual education program models == There are different ways to categorize bilingual education models, one of the most common being distinguishing their end goal. === Maintenance bilingual education === In a maintenance bilingual education program, the goal is for students to continue to learn about and in both languages for the majority of their education. Students in a maintenance bilingual education program should graduate being able to have a discussion about any content area in either language.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that bilingual education should replace all second-language courses."}, {"id": "B", "text": "It defines bilingual education, explains how programs vary, and begins describing program models."}, {"id": "C", "text": "It compares bilingual education with monolingual education in several countries."}, {"id": "D", "text": "It lists the steps for becoming a bilingual teacher."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Bilingual education", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Bilingual_education', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-TS002', 'B', ARRAY['B']::TEXT[], 'The text defines the practice, distinguishes it from language study, explains variation in language use and goals, and then introduces program models.', '{"C": "No countries are compared.", "A": "The text does not advocate replacing language courses.", "D": "Teacher preparation is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CE002', 'HDSAT-RW-M19-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'In bilingual education, students are taught in two (or more) languages. It is distinct from learning a second language as a subject because both languages are used for instruction in different content areas like math, science, and history. The time spent in each language depends on the model. For example, some models focus on providing education in both languages throughout a student''s entire education while others gradually transition to education in only one language. The ultimate goal of bilingual education is fluency and literacy in both languages through a variety of strategies such as translanguaging and recasting. Research on bilingual education has increased since 2008 with translanguaging and culturally responsive pedagogies. New educational models focus on inclusivity for hard of hearing or deaf students with the integration of sign language bilingual education. == Bilingual education program models == There are different ways to categorize bilingual education models, one of the most common being distinguishing their end goal. === Maintenance bilingual education === In a maintenance bilingual education program, the goal is for students to continue to learn about and in both languages for the majority of their education. Students in a maintenance bilingual education program should graduate being able to have a discussion about any content area in either language.', 'Which quotation from the text most directly supports the claim that bilingual education is not the same as studying a language as a subject?', '[{"id": "A", "text": "In bilingual education, students are taught in two (or more) languages."}, {"id": "B", "text": "The time spent in each language depends on the model."}, {"id": "C", "text": "The ultimate goal of bilingual education is fluency and literacy in both languages through a variety of strategies such as translanguaging and recasting."}, {"id": "D", "text": "It is distinct from learning a second language as a subject because both languages are used for instruction in different content areas like math, science, and history."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Bilingual education", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Bilingual_education', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CE002', 'D', ARRAY['D']::TEXT[], 'The correct quotation explicitly distinguishes bilingual education from second-language study and explains that both languages are used to teach content.', '{"A": "This sentence states the languages used but not the contrast with language study.", "B": "This sentence describes variation among models.", "C": "This sentence states the goal rather than the distinction from language courses."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CI003', 'HDSAT-RW-M19-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A green roof or living roof is a roof of a building that is partially or completely covered with vegetation and a growing medium, planted over a waterproofing membrane. It may also include additional layers such as a root barrier and drainage, and irrigation systems. Container gardens on roofs, where plants are maintained in pots, are not generally considered to be true green roofs, although this is debated. Rooftop ponds are another form of green roofs, which are used to treat greywater. Vegetation, soil, drainage layer, root barrier, and irrigation system constitute the green roof. Green roofs serve several purposes for a building, such as absorbing rainwater, providing insulation, creating a habitat for wildlife, and decreasing stress of the people around the roof by providing a more aesthetically pleasing landscape, and helping to lower urban air temperatures and mitigate the heat island effect. Green roofs are suitable for retrofit or redevelopment projects as well as new buildings and can be installed on small garages or larger industrial, commercial and municipal buildings. They effectively use the natural functions of plants to filter water and treat air in urban and suburban landscapes.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Green roofs are layered vegetated roof systems that provide building and environmental benefits."}, {"id": "B", "text": "Green roofs increase urban air temperatures and worsen the heat island effect."}, {"id": "C", "text": "Green roofs are simply potted plants placed on rooftops."}, {"id": "D", "text": "Green roofs are used only on small garages and cannot be installed on large buildings."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Green roof", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Green_roof', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CI003', 'A', ARRAY['A']::TEXT[], 'The passage defines green roofs and their layers, distinguishes them from container gardens, and lists purposes from rainwater absorption to cooling.', '{"C": "The text says container gardens with potted plants are not generally considered true green roofs.", "D": "The text says green roofs can be installed on small garages or larger industrial, commercial and municipal buildings.", "B": "The text says green roofs help lower urban air temperatures and mitigate the heat island effect."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-INF003', 'HDSAT-RW-M19-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A green roof or living roof is a roof of a building that is partially or completely covered with vegetation and a growing medium, planted over a waterproofing membrane. It may also include additional layers such as a root barrier and drainage, and irrigation systems. Container gardens on roofs, where plants are maintained in pots, are not generally considered to be true green roofs, although this is debated. Rooftop ponds are another form of green roofs, which are used to treat greywater. Vegetation, soil, drainage layer, root barrier, and irrigation system constitute the green roof. Green roofs serve several purposes for a building, such as absorbing rainwater, providing insulation, creating a habitat for wildlife, and decreasing stress of the people around the roof by providing a more aesthetically pleasing landscape, and helping to lower urban air temperatures and mitigate the heat island effect. Green roofs are suitable for retrofit or redevelopment projects as well as new buildings and can be installed on small garages or larger industrial, commercial and municipal buildings. They effectively use the natural functions of plants to filter water and treat air in urban and suburban landscapes.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-INF003', 'D', ARRAY['D']::TEXT[], 'The stated benefits of absorbing rainwater and lowering urban temperatures support reductions in runoff and heat effects.', '{"A": "The text says green roofs help mitigate the heat island effect.", "B": "The text lists drainage as a layer within the roof system, not something made unnecessary.", "C": "Absorbing rainwater does not mean preventing all of it from reaching the ground."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-TS003', 'HDSAT-RW-M19-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A green roof or living roof is a roof of a building that is partially or completely covered with vegetation and a growing medium, planted over a waterproofing membrane. It may also include additional layers such as a root barrier and drainage, and irrigation systems. Container gardens on roofs, where plants are maintained in pots, are not generally considered to be true green roofs, although this is debated. Rooftop ponds are another form of green roofs, which are used to treat greywater. Vegetation, soil, drainage layer, root barrier, and irrigation system constitute the green roof. Green roofs serve several purposes for a building, such as absorbing rainwater, providing insulation, creating a habitat for wildlife, and decreasing stress of the people around the roof by providing a more aesthetically pleasing landscape, and helping to lower urban air temperatures and mitigate the heat island effect. Green roofs are suitable for retrofit or redevelopment projects as well as new buildings and can be installed on small garages or larger industrial, commercial and municipal buildings. They effectively use the natural functions of plants to filter water and treat air in urban and suburban landscapes.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It traces the history of green roof construction in ancient cities."}, {"id": "B", "text": "It compares the costs of green roofs with solar panels."}, {"id": "C", "text": "It argues that green roofs are unsuitable for retrofitting."}, {"id": "D", "text": "It defines green roofs and their layers, distinguishes them from container gardens, and lists their purposes and suitable buildings."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Green roof", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Green_roof', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-TS003', 'D', ARRAY['D']::TEXT[], 'The text moves from definition and construction, to a clarification about container gardens, to functions and installation options.', '{"A": "No historical account is given.", "C": "The text says green roofs are suitable for retrofit or redevelopment projects.", "B": "Solar panels are not mentioned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CE003', 'HDSAT-RW-M19-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A green roof or living roof is a roof of a building that is partially or completely covered with vegetation and a growing medium, planted over a waterproofing membrane. It may also include additional layers such as a root barrier and drainage, and irrigation systems. Container gardens on roofs, where plants are maintained in pots, are not generally considered to be true green roofs, although this is debated. Rooftop ponds are another form of green roofs, which are used to treat greywater. Vegetation, soil, drainage layer, root barrier, and irrigation system constitute the green roof. Green roofs serve several purposes for a building, such as absorbing rainwater, providing insulation, creating a habitat for wildlife, and decreasing stress of the people around the roof by providing a more aesthetically pleasing landscape, and helping to lower urban air temperatures and mitigate the heat island effect. Green roofs are suitable for retrofit or redevelopment projects as well as new buildings and can be installed on small garages or larger industrial, commercial and municipal buildings. They effectively use the natural functions of plants to filter water and treat air in urban and suburban landscapes.', 'Which quotation from the text most directly supports the claim that green roofs can mitigate the urban heat island effect?', '[{"id": "A", "text": "It may also include additional layers such as a root barrier and drainage, and irrigation systems."}, {"id": "B", "text": "Green roofs serve several purposes for a building, such as absorbing rainwater, providing insulation, creating a habitat for wildlife, and decreasing stress of the people around the roof by providing a more aesthetically pleasing landscape, and helping to lower urban air temperatures and mitigate the heat island effect."}, {"id": "C", "text": "A green roof or living roof is a roof of a building that is partially or completely covered with vegetation and a growing medium, planted over a waterproofing membrane."}, {"id": "D", "text": "Green roofs are suitable for retrofit or redevelopment projects as well as new buildings and can be installed on small garages or larger industrial, commercial and municipal buildings."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Green roof", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Green_roof', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CE003', 'B', ARRAY['B']::TEXT[], 'The correct quotation names lowering urban air temperatures and mitigating the heat island effect among the purposes green roofs serve.', '{"C": "This sentence defines a green roof.", "A": "This sentence describes additional layers.", "D": "This sentence describes where green roofs can be installed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CI004', 'HDSAT-RW-M19-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Vertical farming is the practice of growing crops in vertically and horizontally stacked layers. It often incorporates controlled-environment agriculture, which aims to optimize plant growth, and soilless farming techniques such as hydroponics, aquaponics, and aeroponics. Some common choices of structures to house vertical farming systems include buildings, shipping containers, underground tunnels, and abandoned mine shafts. The modern concept of vertical farming was proposed in 1999 by Dickson Despommier, professor of Public and Environmental Health at Columbia University. Despommier and his students came up with a design for a skyscraper farm that could feed 50,000 people. Although the design has not yet been built, it successfully popularized the idea of vertical farming. Current applications of vertical farming coupled with other state-of-the-art technologies, such as specialized LED lights, have resulted in over 10 times the crop yield as would be received through traditional farming methods. The main advantage of utilizing vertical farming technologies is the increased crop yield that comes with a smaller unit area of land requirement. The increased ability to cultivate a larger variety of crops at once because crops do not share the same plots of land while growing is another sought-after advantage. Additionally, crops are resistant to weather disruptions because of their placement indoors, meaning fewer crops lost to extreme or unexpected weather occurrences.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Vertical farming produces lower yields than traditional farming but requires less technology."}, {"id": "B", "text": "Vertical farming grows crops in stacked indoor layers, producing high yields on small areas and protecting crops from weather."}, {"id": "C", "text": "Vertical farming was proposed in 1999 and has since been abandoned."}, {"id": "D", "text": "Vertical farming grows crops in open fields using traditional soil methods."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Vertical farming", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Vertical_farming', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CI004', 'B', ARRAY['B']::TEXT[], 'The passage defines vertical farming and its techniques, describes its origin, and lists advantages in yield, land use, crop variety and weather resilience.', '{"D": "The text says vertical farming grows crops in vertically and horizontally stacked layers, often with soilless techniques.", "C": "The text says the idea was proposed in 1999 and that current applications exist.", "A": "The text says current applications have resulted in over 10 times the crop yield of traditional methods."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-INF004', 'HDSAT-RW-M19-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Vertical farming is the practice of growing crops in vertically and horizontally stacked layers. It often incorporates controlled-environment agriculture, which aims to optimize plant growth, and soilless farming techniques such as hydroponics, aquaponics, and aeroponics. Some common choices of structures to house vertical farming systems include buildings, shipping containers, underground tunnels, and abandoned mine shafts. The modern concept of vertical farming was proposed in 1999 by Dickson Despommier, professor of Public and Environmental Health at Columbia University. Despommier and his students came up with a design for a skyscraper farm that could feed 50,000 people. Although the design has not yet been built, it successfully popularized the idea of vertical farming. Current applications of vertical farming coupled with other state-of-the-art technologies, such as specialized LED lights, have resulted in over 10 times the crop yield as would be received through traditional farming methods. The main advantage of utilizing vertical farming technologies is the increased crop yield that comes with a smaller unit area of land requirement. The increased ability to cultivate a larger variety of crops at once because crops do not share the same plots of land while growing is another sought-after advantage. Additionally, crops are resistant to weather disruptions because of their placement indoors, meaning fewer crops lost to extreme or unexpected weather occurrences.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-INF004', 'A', ARRAY['A']::TEXT[], 'The passage ties indoor stacked growing to a smaller land requirement and resistance to weather disruptions.', '{"B": "The text describes controlled-environment agriculture and specialized LED lights, which implies light and water are managed, not unnecessary.", "C": "The text describes current applications and advantages but not a complete replacement of traditional farms.", "D": "Mine shafts are one possible structure, not the only one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-TS004', 'HDSAT-RW-M19-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Vertical farming is the practice of growing crops in vertically and horizontally stacked layers. It often incorporates controlled-environment agriculture, which aims to optimize plant growth, and soilless farming techniques such as hydroponics, aquaponics, and aeroponics. Some common choices of structures to house vertical farming systems include buildings, shipping containers, underground tunnels, and abandoned mine shafts. The modern concept of vertical farming was proposed in 1999 by Dickson Despommier, professor of Public and Environmental Health at Columbia University. Despommier and his students came up with a design for a skyscraper farm that could feed 50,000 people. Although the design has not yet been built, it successfully popularized the idea of vertical farming. Current applications of vertical farming coupled with other state-of-the-art technologies, such as specialized LED lights, have resulted in over 10 times the crop yield as would be received through traditional farming methods. The main advantage of utilizing vertical farming technologies is the increased crop yield that comes with a smaller unit area of land requirement. The increased ability to cultivate a larger variety of crops at once because crops do not share the same plots of land while growing is another sought-after advantage. Additionally, crops are resistant to weather disruptions because of their placement indoors, meaning fewer crops lost to extreme or unexpected weather occurrences.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares vertical farming with hydroponics as competing methods."}, {"id": "B", "text": "It explains how to build a shipping container farm step by step."}, {"id": "C", "text": "It defines vertical farming and its techniques, describes its origin, and lists its advantages."}, {"id": "D", "text": "It argues that vertical farming cannot feed large populations."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Vertical farming", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Vertical_farming', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-TS004', 'C', ARRAY['C']::TEXT[], 'The text opens with definition and methods, notes Despommier''s 1999 proposal, and closes with the benefits of current applications.', '{"A": "Hydroponics is named as a soilless technique used within vertical farming, not as a competitor.", "D": "The text mentions a design that could feed 50,000 people but does not argue that vertical farming cannot feed populations.", "B": "No construction instructions are given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CE004', 'HDSAT-RW-M19-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'Vertical farming is the practice of growing crops in vertically and horizontally stacked layers. It often incorporates controlled-environment agriculture, which aims to optimize plant growth, and soilless farming techniques such as hydroponics, aquaponics, and aeroponics. Some common choices of structures to house vertical farming systems include buildings, shipping containers, underground tunnels, and abandoned mine shafts. The modern concept of vertical farming was proposed in 1999 by Dickson Despommier, professor of Public and Environmental Health at Columbia University. Despommier and his students came up with a design for a skyscraper farm that could feed 50,000 people. Although the design has not yet been built, it successfully popularized the idea of vertical farming. Current applications of vertical farming coupled with other state-of-the-art technologies, such as specialized LED lights, have resulted in over 10 times the crop yield as would be received through traditional farming methods. The main advantage of utilizing vertical farming technologies is the increased crop yield that comes with a smaller unit area of land requirement. The increased ability to cultivate a larger variety of crops at once because crops do not share the same plots of land while growing is another sought-after advantage. Additionally, crops are resistant to weather disruptions because of their placement indoors, meaning fewer crops lost to extreme or unexpected weather occurrences.', 'Which quotation from the text most directly supports the claim that vertical farming can produce more food per unit of land?', '[{"id": "A", "text": "Some common choices of structures to house vertical farming systems include buildings, shipping containers, underground tunnels, and abandoned mine shafts."}, {"id": "B", "text": "The modern concept of vertical farming was proposed in 1999 by Dickson Despommier, professor of Public and Environmental Health at Columbia University."}, {"id": "C", "text": "Additionally, crops are resistant to weather disruptions because of their placement indoors, meaning fewer crops lost to extreme or unexpected weather occurrences."}, {"id": "D", "text": "Current applications of vertical farming coupled with other state-of-the-art technologies, such as specialized LED lights, have resulted in over 10 times the crop yield as would be received through traditional farming methods."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Vertical farming", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Vertical_farming', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CE004', 'D', ARRAY['D']::TEXT[], 'The correct quotation reports over ten times the crop yield of traditional farming methods.', '{"B": "This sentence gives the origin of the modern concept.", "A": "This sentence lists structures used for vertical farming.", "C": "This sentence describes weather resilience, not yield per unit of land."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CI005', 'HDSAT-RW-M19-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Open access (OA) is a set of principles and a range of practices through which nominally copyrightable publications are delivered to readers free of access charges or other barriers. With open access strictly defined (according to the 2001 definition), or libre open access, barriers to copying or reuse are also reduced or removed by applying an open license for copyright, which regulates post-publication uses of the work. The main focus of the open access movement has been on peer reviewed research literature, and more specifically on academic journals. This is because: such publications have been a subject of serials crisis, unlike newspapers, magazines and fiction writing. The main difference between these two groups is in demand elasticity: whereas an English literature curriculum can substitute Harry Potter and the Philosopher''s Stone with a public domain alternative, such as A Voyage to Lilliput, an emergency room physician treating a patient for a life-threatening urushiol poisoning cannot substitute the most recent, but paywalled review article on this topic with a 90-year-old copyright-expired article that was published before the invention of prednisone in 1954. the authors of research papers are not paid in any way, so they do not suffer any monetary losses, when they switch from behind paywall to open access publishing, especially, if they use diamond open access media.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Open access requires authors to pay readers for permission to publish."}, {"id": "B", "text": "Open access eliminates copyright entirely for all publications."}, {"id": "C", "text": "Open access removes price and permission barriers to research, especially journal articles, because readers often cannot substitute other sources."}, {"id": "D", "text": "Open access applies mainly to newspapers, magazines and fiction."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Open access", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Open_access', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CI005', 'C', ARRAY['C']::TEXT[], 'The passage defines open access and libre open access, explains why journals are the focus, and contrasts research articles with substitutable creative works.', '{"A": "The text describes delivering publications free of access charges and reducing barriers with an open license; it does not describe paying readers.", "D": "The text says the main focus has been peer-reviewed research literature, especially academic journals.", "B": "The text says open access uses an open license to regulate post-publication uses, not that copyright is eliminated."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-INF005', 'HDSAT-RW-M19-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Open access (OA) is a set of principles and a range of practices through which nominally copyrightable publications are delivered to readers free of access charges or other barriers. With open access strictly defined (according to the 2001 definition), or libre open access, barriers to copying or reuse are also reduced or removed by applying an open license for copyright, which regulates post-publication uses of the work. The main focus of the open access movement has been on peer reviewed research literature, and more specifically on academic journals. This is because: such publications have been a subject of serials crisis, unlike newspapers, magazines and fiction writing. The main difference between these two groups is in demand elasticity: whereas an English literature curriculum can substitute Harry Potter and the Philosopher''s Stone with a public domain alternative, such as A Voyage to Lilliput, an emergency room physician treating a patient for a life-threatening urushiol poisoning cannot substitute the most recent, but paywalled review article on this topic with a 90-year-old copyright-expired article that was published before the invention of prednisone in 1954. the authors of research papers are not paid in any way, so they do not suffer any monetary losses, when they switch from behind paywall to open access publishing, especially, if they use diamond open access media.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-INF005', 'A', ARRAY['A']::TEXT[], 'The passage states that unpaid authors suffer no monetary losses when they switch to open access, which supports the inference about royalties.', '{"B": "The text''s whole point is that open access changes who can read the work by removing access charges.", "D": "The text says libre open access applies an open license, so licensing is part of the move.", "C": "The move is defined by removing access charges."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-TS005', 'HDSAT-RW-M19-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Open access (OA) is a set of principles and a range of practices through which nominally copyrightable publications are delivered to readers free of access charges or other barriers. With open access strictly defined (according to the 2001 definition), or libre open access, barriers to copying or reuse are also reduced or removed by applying an open license for copyright, which regulates post-publication uses of the work. The main focus of the open access movement has been on peer reviewed research literature, and more specifically on academic journals. This is because: such publications have been a subject of serials crisis, unlike newspapers, magazines and fiction writing. The main difference between these two groups is in demand elasticity: whereas an English literature curriculum can substitute Harry Potter and the Philosopher''s Stone with a public domain alternative, such as A Voyage to Lilliput, an emergency room physician treating a patient for a life-threatening urushiol poisoning cannot substitute the most recent, but paywalled review article on this topic with a 90-year-old copyright-expired article that was published before the invention of prednisone in 1954. the authors of research papers are not paid in any way, so they do not suffer any monetary losses, when they switch from behind paywall to open access publishing, especially, if they use diamond open access media.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It traces the history of the serials crisis from its origins."}, {"id": "B", "text": "It compares diamond open access with traditional subscriptions in detail."}, {"id": "C", "text": "It argues that all books should be published without copyright."}, {"id": "D", "text": "It defines open access, explains why journals are its focus, and contrasts research articles with substitutable works."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Open access", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Open_access', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-TS005', 'D', ARRAY['D']::TEXT[], 'The text defines the concept, identifies academic journals as the main focus, and uses the substitution argument to explain why access matters there.', '{"A": "The serials crisis is mentioned as a reason journals are the focus, not traced historically.", "C": "The text discusses research literature and does not call for eliminating copyright for books.", "B": "Diamond open access is mentioned only as an example of publishing without author fees."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CE005', 'HDSAT-RW-M19-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'Open access (OA) is a set of principles and a range of practices through which nominally copyrightable publications are delivered to readers free of access charges or other barriers. With open access strictly defined (according to the 2001 definition), or libre open access, barriers to copying or reuse are also reduced or removed by applying an open license for copyright, which regulates post-publication uses of the work. The main focus of the open access movement has been on peer reviewed research literature, and more specifically on academic journals. This is because: such publications have been a subject of serials crisis, unlike newspapers, magazines and fiction writing. The main difference between these two groups is in demand elasticity: whereas an English literature curriculum can substitute Harry Potter and the Philosopher''s Stone with a public domain alternative, such as A Voyage to Lilliput, an emergency room physician treating a patient for a life-threatening urushiol poisoning cannot substitute the most recent, but paywalled review article on this topic with a 90-year-old copyright-expired article that was published before the invention of prednisone in 1954. the authors of research papers are not paid in any way, so they do not suffer any monetary losses, when they switch from behind paywall to open access publishing, especially, if they use diamond open access media.', 'Which quotation from the text most directly supports the claim that some readers cannot substitute an older free article for current research?', '[{"id": "A", "text": "Open access (OA) is a set of principles and a range of practices through which nominally copyrightable publications are delivered to readers free of access charges or other barriers."}, {"id": "B", "text": "whereas an English literature curriculum can substitute Harry Potter and the Philosopher''s Stone with a public domain alternative, such as A Voyage to Lilliput, an emergency room physician treating a patient for a life-threatening urushiol poisoning cannot substitute the most recent, but paywalled review article on this topic with a 90-year-old copyright-expired article that was published before the invention of prednisone in 1954."}, {"id": "C", "text": "The main focus of the open access movement has been on peer reviewed research literature, and more specifically on academic journals."}, {"id": "D", "text": "the authors of research papers are not paid in any way, so they do not suffer any monetary losses, when they switch from behind paywall to open access publishing, especially, if they use diamond open access media."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Open access", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Open_access', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CE005', 'B', ARRAY['B']::TEXT[], 'The correct quotation contrasts a substitutable literature curriculum with a physician who needs current research that an old article cannot replace.', '{"A": "This sentence defines open access.", "C": "This sentence identifies the movement''s focus.", "D": "This sentence concerns authors'' pay, not readers'' ability to substitute sources."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-CI006', 'HDSAT-RW-M19-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Citizen science is research conducted with the participation of the general public, amateur or nonprofessional researchers, or participants from the fields of science, social science, and many other disciplines. The exact definition of "citizen science" varies, with different individuals and organizations having their own specific interpretations of its scope. Citizen science is employed in a wide range of areas of study, including ecology, biology, conservation, health and medical research, astronomy, media and communications, and information science. The applications and functions of citizen science in research projects are multifaceted. Citizen science can be used as a methodology in which public volunteers help in data collection and classification, thereby improving the scientific community''s capacity. Citizen science observations can be used to uncover general trends in native habitats across broad spatial and temporal scales, extending data collection beyond the capacity of individual researchers. These observations can then be integrated with findings from designed experiments to provide a more complete understanding of natural variation and ecological processes. Citizen science can also involve more direct involvement from the public, with communities initiating projects researching environment and health hazards within their own communities.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Citizen science is limited to professional scientists working in laboratories."}, {"id": "B", "text": "Citizen science involves the public in research in varied ways, from collecting data to initiating community projects, expanding what researchers can study."}, {"id": "C", "text": "Citizen science is used only in astronomy."}, {"id": "D", "text": "Citizen science replaces designed experiments entirely."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Citizen science", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Citizen_science', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-CI006', 'B', ARRAY['B']::TEXT[], 'The passage defines citizen science, notes that its definition varies, lists fields, and describes roles ranging from data collection to community-initiated research.', '{"A": "The text says citizen science is research conducted with the participation of the general public, amateur or nonprofessional researchers.", "D": "The text says observations can be integrated with findings from designed experiments, not replace them.", "C": "The text lists ecology, biology, conservation, health, astronomy, media and information science."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M19-INF006', 'HDSAT-RW-M19-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Citizen science is research conducted with the participation of the general public, amateur or nonprofessional researchers, or participants from the fields of science, social science, and many other disciplines. The exact definition of "citizen science" varies, with different individuals and organizations having their own specific interpretations of its scope. Citizen science is employed in a wide range of areas of study, including ecology, biology, conservation, health and medical research, astronomy, media and communications, and information science. The applications and functions of citizen science in research projects are multifaceted. Citizen science can be used as a methodology in which public volunteers help in data collection and classification, thereby improving the scientific community''s capacity. Citizen science observations can be used to uncover general trends in native habitats across broad spatial and temporal scales, extending data collection beyond the capacity of individual researchers. These observations can then be integrated with findings from designed experiments to provide a more complete understanding of natural variation and ecological processes. Citizen science can also involve more direct involvement from the public, with communities initiating projects researching environment and health hazards within their own communities.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M19-INF006', 'A', ARRAY['A']::TEXT[], 'The passage states that citizen observations extend collection beyond individual researchers and can uncover broad-scale trends.', '{"D": "The text says observations can be integrated with designed experiments, not that experiments become unnecessary.", "B": "The text says observations uncover trends in native habitats across broad spatial and temporal scales, the opposite of a single habitat.", "C": "The text says volunteers help in data collection and classification, so classification remains part of the work."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
